mapper.insert:
INSERT INTO chat_message_read
    (message_id, session_id, user_id, read_time)
SELECT message.id,
       message.session_id,
       #{userId},
       #{readTime}
FROM chat_message message
INNER JOIN chat_message anchor
        ON anchor.id = #{lastReadMessageId}
       AND anchor.session_id = #{sessionId}
WHERE message.session_id = #{sessionId}
  AND message.sender_id != #{userId}
  AND message.recalled = 0
  AND (
        message.create_time < anchor.create_time
        OR (
            message.create_time = anchor.create_time
            AND message.id <= anchor.id
        )
  )
ON DUPLICATE KEY UPDATE read_time = VALUES(read_time)

mapper.select:
SELECT COUNT(*)
FROM chat_message message
WHERE message.session_id = #{sessionId}
  AND message.sender_id != #{userId}
  AND message.recalled = 0
  AND NOT EXISTS (
        SELECT 1
        FROM chat_message_read read_state
        WHERE read_state.message_id = message.id
          AND read_state.user_id = #{userId}
  )
